#include <stdio.h>
#include <stdlib.h>

#define LOG 18

static int head[100005];
static int to[100005];
static int nxt[100005];
static int edge_cnt = 0;

static int up[LOG][100005];
static int tin[100005];
static int tout[100005];
static int is_restructured[100005];
static int bit[100005];
static int n_val;

static void add_edge(int u, int v) {
    to[edge_cnt] = v;
    nxt[edge_cnt] = head[u];
    head[u] = edge_cnt++;
}

static void bit_add(int idx, int val) {
    for (; idx <= n_val + 2; idx += idx & -idx) {
        bit[idx] += val;
    }
}

static int bit_query(int idx) {
    int sum = 0;
    for (; idx > 0; idx -= idx & -idx) {
        sum += bit[idx];
    }
    return sum;
}

static int get_kth_ancestor(int u, int k) {
    for (int i = 0; i < LOG; i++) {
        if ((k >> i) & 1) {
            u = up[i][u];
        }
    }
    return u;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    n_val = n;

    for (int i = 1; i <= n; i++) {
        head[i] = -1;
    }

    up[0][1] = 0;
    for (int i = 2; i <= n; i++) {
        int p;
        scanf("%d", &p);
        up[0][i] = p;
        add_edge(p, i);
    }

    for (int j = 1; j < LOG; j++) {
        for (int i = 1; i <= n; i++) {
            up[j][i] = up[j - 1][up[j - 1][i]];
        }
    }

    int *stack_u = (int *)malloc((n + 5) * sizeof(int));
    int *stack_edge = (int *)malloc((n + 5) * sizeof(int));
    int top = 0;
    int timer = 0;

    stack_u[top] = 1;
    stack_edge[top] = head[1];
    tin[1] = ++timer;

    while (top >= 0) {
        int u = stack_u[top];
        int e = stack_edge[top];
        if (e != -1) {
            stack_edge[top] = nxt[e];
            int v = to[e];
            tin[v] = ++timer;
            top++;
            stack_u[top] = v;
            stack_edge[top] = head[v];
        } else {
            tout[u] = timer;
            top--;
        }
    }

    free(stack_u);
    free(stack_edge);

    int q;
    if (scanf("%d", &q) != 1) return 0;

    for (int qi = 0; qi < q; qi++) {
        int type;
        scanf("%d", &type);
        if (type == 1) {
            int u, k;
            scanf("%d %d", &u, &k);
            int cnt_u = bit_query(tin[u]);
            if (cnt_u == 0) {
                printf("%d\n", get_kth_ancestor(u, k));
            } else {
                int x = u;
                for (int i = LOG - 1; i >= 0; i--) {
                    int p = up[i][x];
                    if (p != 0 && bit_query(tin[p]) > 0) {
                        x = p;
                    }
                }
                int v = up[0][x];
                if (k == 1) {
                    printf("%d\n", v);
                } else {
                    printf("%d\n", get_kth_ancestor(v, k - 1));
                }
            }
        } else if (type == 2) {
            int v;
            scanf("%d", &v);
            int cnt_v = bit_query(tin[v]);
            if (cnt_v == 0 && !is_restructured[v]) {
                is_restructured[v] = 1;
                if (tin[v] + 1 <= tout[v]) {
                    bit_add(tin[v] + 1, 1);
                    bit_add(tout[v] + 1, -1);
                }
            }
        }
    }

    return 0;
}
